changeSet.sql:
CREATE TABLE wf_test.sandbox_request (
 id BIGINT IDENTITY(1,1) NOT NULL PRIMARY KEY, name NVARCHAR(200) NOT NULL,
 created_by NVARCHAR(200) COLLATE Latin1_General_100_BIN2 NOT NULL,
 created_at DATETIME2(7) NOT NULL, lock_version BIGINT NOT NULL, instance_id BIGINT NULL,
 CONSTRAINT ck_console_request_version CHECK(lock_version>=0),
 CONSTRAINT ck_console_request_instance CHECK(instance_id IS NULL OR instance_id>0)
);
CREATE UNIQUE INDEX ux_console_request_instance ON wf_test.sandbox_request(instance_id) WHERE instance_id IS NOT NULL;
